document.addEventListener("DOMContentLoaded",function(){let t=null;document.getElementById("myTable").addEventListener("click",function(e){if(e.target.closest(".collapse"))return;const n=e.target.closest(".btn-nesting"),o=e.target.closest("tr[data-id]");if(!o)return;const s=o.querySelector(".btn-nesting"),c=o.classList.contains("selected-row");if(!n&&s&&s.click(),document.querySelectorAll("#myTable > tbody > tr.selected-row").forEach(t=>t.classList.remove("selected-row")),c)return t=null,document.getElementById("edit-btn").href="#",document.getElementById("edit-btn").innerHTML='<i class="buttons-content bi bi-pencil-square"></i> Συντήρηση',document.getElementById("delete-btn").href="#",void(document.getElementById("delete-btn").innerHTML='<i class="buttons-content bi bi-trash"></i> Διαγραφή');o.classList.add("selected-row"),t=o.dataset.id,document.getElementById("edit-btn").href=`/krathseis/genika/edit/${t}`,document.getElementById("edit-btn").innerHTML='<i class="buttons-content bi bi-pencil-square"></i> Συντήρηση Κράτησης',adjustFontSizeToFit("edit-btn",15),document.getElementById("delete-btn").innerHTML='<i class="buttons-content bi bi-trash"></i> Διαγραφή Κράτησης',adjustFontSizeToFit("delete-btn",15)}),document.getElementById("delete-btn").addEventListener("click",async function(e){if(e.preventDefault(),!t)return;console.log(t);const n=`/krathseis/genika/delete/${t}`;if((await Swal.fire({title:"Είστε σίγουρος / η;",html:"ΠΡΟΣΟΧΗ!!! Δεν θα μπορείτε να αναιρέσετε αυτή την ενέργεια!  Θα διαγραφεί επίσης και όλο το ιστορικό των Ποσοστών των Κρατήσεων και υπάρχει <strong>μεγάλη πιθανότητα</strong> μη καλής λειτουργίας της εφαρμογής...",icon:"error",showCancelButton:!0,focusConfirm:!0,confirmButtonColor:"#3085d6",cancelButtonColor:"#3332049a",confirmButtonText:"Διαγραφή",cancelButtonText:"Ακύρωση",customClass:{confirmButton:"class-error custom-confirm-button custom-swal-button",cancelButton:"custom-cancel-button custom-swal-button"},didOpen:()=>{Swal.getCancelButton().focus()}})).isConfirmed)try{const t=await fetch(n,{method:"DELETE",headers:{"Content-Type":"application/json"}});if(!t.ok)throw new Error("Network response was not ok");const e=await t.json();Swal.fire({icon:"success",title:"Επιτυχής Διαγραφή της Κράτησης",timer:3e3,confirmButtonText:"Κλείσιμο",customClass:{confirmButton:"class-success custom-confirm-button custom-swal-button"},willClose:()=>{window.location.href=e.redirectUrl}})}catch(t){Swal.fire({icon:"error",title:"Σφάλμα κατά τη Διαγραφή της Κράτησης",text:'Επικοινωνήστε με τον διαχειριστή μέσω της φόρμας <strong>"Επικοινωνία"</strong>',timer:3e3,confirmButtonText:"Κλείσιμο",customClass:{confirmButton:"class-normal custom-confirm-button custom-swal-button"},willClose:()=>{window.location.href="/krathseis/krathseis"}})}})});